// Build CLI args for the bag scanner.
// Expects: { path, knobs?, stages?, enable_redaction_signatures? }
const body = items[0].json;
if (!body.path) { throw new Error('bag specialist needs a .bag path'); }
const args = ['run', 'bag', body.path];
if (body.knobs) { args.push('--knobs', JSON.stringify(body.knobs)); }
if (body.stages) { args.push('--stages', Array.isArray(body.stages) ? body.stages.join(',') : body.stages); }
if (body.enable_redaction_signatures) { args.push('--enable-redaction-signatures'); }
return [{ json: { argv: args.join(' '), runner: $env.CESAROPS_RUNNER || '/home/cesarops/wreckhunter2000-1/n8n/pipeline_runner.sh' } }];

// Parse MissionReport; split physical wrecks vs masked redactions.
const out = items[0].json.stdout || '{}';
let report;
try { report = JSON.parse(out); } catch (e) { return [{ json: { error: 'bad JSON from bag-scan', raw: out.slice(0, 500) } }]; }
const dets = report.detections || [];
const wrecks = dets.filter(d => d.signature_type === 'physical_wreck');
const redactions = dets.filter(d => d.signature_type === 'masked_redaction_flat');
return [{ json: {
  pipeline: 'bag',
  file: report.file,
  epsg: report.epsg_code,
  physical_wreck_count: report.physical_wreck_count,
  masked_redaction_count: report.masked_redaction_count,
  top_wrecks: wrecks.slice(0, 10),
  top_redactions: redactions.slice(0, 10),
  report
} }];
